package kr.memorynotes;
import android.view.View;import android.widget.*;import java.util.*;
public class ReviewScreen {
 final MainActivity a;final ArrayList<Note> notes;int index=0;boolean revealed=false;
 ReviewScreen(MainActivity a,ArrayList<Note> notes){this.a=a;this.notes=notes;}
 void show(){a.editor=null;if(index>=notes.size()){a.review=null;a.shell("복습을 마쳤어요!",notes.size()+"개의 노트를 돌아봤습니다.",false);a.backAction=()->a.show("홈");a.content.addView(a.u.primary("홈으로",()->a.show("홈")));return;}Note n=notes.get(index);a.shell((index+1)+" / "+notes.size()+"  오늘의 기억",a.meta(n),false);a.u.pictures=n.images;a.backAction=()->a.show("홈");LinearLayout c=a.u.card(a.content);if(n.type.equals("일반 노트"))c.addView(a.u.title(n.title));c.addView(a.u.studyLegend());a.u.gap(c,12);if(n.type.equals("일반 노트")){c.addView(a.u.studyContent(n.body,21,true,!revealed));if(StudyText.parts(n.body,false,true).stream().noneMatch(part->part.kind==StudyText.CLOZE)&&!revealed)c.addView(a.u.text("내용을 읽고 핵심을 떠올려보세요. 수정 화면에서 여러 문구를 가림으로 지정할 수 있습니다.",13,a.u.muted));}else{c.addView(a.u.text(n.question,21,a.u.ink));if(revealed){a.u.gap(c,15);c.addView(a.u.text("정답 · 해설",13,a.u.green));c.addView(a.u.studyContent(n.answer,21,true,false));if(!n.mine.isEmpty())c.addView(a.u.text("내 답\n"+n.mine,16,a.u.muted));if(n.type.equals("오답노트")&&!n.body.isEmpty())c.addView(a.u.studyContent(n.body,16,true,false));}}ImageMaskView.appendImages(a,c,n,!revealed,false);if(revealed){if(!n.reason.isEmpty())c.addView(a.u.text("틀린 이유\n"+n.reason,16,a.u.ink));if(!n.caution.isEmpty())c.addView(a.u.text("다음에 확인할 것\n"+n.caution,16,a.u.ink));a.content.addView(a.u.text("얼마나 기억했나요?",18,a.u.ink));for(int r=0;r<3;r++){final int rating=r;String label=new String[]{"모름 · 내일 다시","헷갈림 · 3일 뒤","외웠음 · "+(n.streak==0?7:n.streak==1?14:30)+"일 뒤"}[r];a.content.addView(a.u.button(label,()->{try{a.db.review(n,rating);index++;revealed=false;show();}catch(Exception e){a.error(e);}}));}}else a.content.addView(a.u.primary("정답 · 가린 부분 확인",()->{revealed=true;show();}));a.content.addView(a.u.button("이번에는 건너뛰기",()->{index++;revealed=false;show();}));}
}
